'use client';

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import type { ReactNode } from 'react';
import { CheckIcon } from 'lucide-react';
import { Alert, AlertDescription, AlertTitle } from '@/components/ui/alert';
import { Button } from '@/components/ui/button';
import { Card, CardAction, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card';
import { ToggleGroup, ToggleGroupItem } from '@/components/ui/toggle-group';
import { MockupViewer } from '../mockup-viewer/mockup-viewer';
import { usePhone } from '../utils/use-media';
import type { ShadcnTheme } from '../mockup-viewer/mockup-viewer';
import { besideLooks, parseLooks, swatches } from './looks';
import type { Look, Looks } from './looks';

export { isLooksPath, parseLooks, parseShadcnTheme, swatches, besideLooks, shadcnValue, SHADCN_COLOR_VARIABLES, SHADCN_SHAPE_VARIABLES } from './looks';
export type { Look, Looks, LayoutVariant } from './looks';


/** The person pressed Pick: the host says it in the conversation (or records it); the viewer only marks it. */
export interface LookPick {
  readonly kind: 'look' | 'layout';
  readonly id: string;
  readonly label: string;
  /** The looks file the pick was made in. */
  readonly path: string;
}

export interface LooksViewerProps {
  readonly text: string;
  readonly path?: string | undefined;
  /** Another file of the workspace as text (the artifact panel's `read`): the key screen and the layouts, next to the looks file. */
  readonly read?: ((path: string) => Promise<string | undefined>) | undefined;
  readonly onPick?: ((pick: LookPick) => void) | undefined;
  readonly locale?: 'en' | 'fr' | undefined;
  readonly onReady?: (() => void) | undefined;
  readonly onFailed?: ((reason: string) => void) | undefined;
}

const LABELS = {
  en: { looks: 'Pick a look', layouts: 'Pick a layout', layoutsIn: (look: string) => `In the ${look} look`, pick: 'Pick', picked: 'Picked', light: 'Light', dark: 'Dark',
    loading: 'Loading the looks…', missing: 'The key screen cannot be read.', invalid: 'These looks cannot be shown', font: 'Font', radius: 'Roundness', look: (label: string) => `${label} look`, layout: (label: string) => `${label} layout` },
  fr: { looks: 'Choisir un style', layouts: 'Choisir une mise en page', layoutsIn: (look: string) => `Dans le style ${look}`, pick: 'Choisir', picked: 'Choisi', light: 'Clair', dark: 'Sombre',
    loading: 'Chargement des styles…', missing: "L'écran clé est illisible.", invalid: 'Ces styles ne peuvent pas être affichés', font: 'Police', radius: 'Arrondi', look: (label: string) => `Style ${label}`, layout: (label: string) => `Mise en page ${label}` },
} as const;

/** The key screen drawn at a desktop (or, in a narrow column, phone) width and scaled into the card, so a look reads as the whole app. */
function ScaledMockup({ text, theme, mode, title, onReady }: { readonly text: string; readonly theme: ShadcnTheme; readonly mode?: 'light' | 'dark' | undefined; readonly title: string; readonly onReady: () => void }) {
  const outer = useRef<HTMLDivElement>(null);
  const [width, setWidth] = useState(0);
  useLayoutEffect(() => {
    const element = outer.current;
    if (!element) return undefined;
    const measure = () => setWidth(element.getBoundingClientRect().width);
    measure();
    if (typeof ResizeObserver === 'undefined') return undefined;
    const observer = new ResizeObserver(measure);
    observer.observe(element);
    return () => observer.disconnect();
  }, []);
  // A phone draws the phone layout of the screen; a narrow column on a desktop still draws the desktop one, smaller.
  const phone = usePhone();
  const virtual = phone ? { w: 390, h: 640 } : { w: 1024, h: 600 };
  const scale = width > 0 ? width / virtual.w : 0.5;
  return <div ref={outer} data-testid="looks-frame" className="relative w-full overflow-hidden bg-muted" style={{ height: Math.round(virtual.h * scale) }}>
    <div className="absolute top-0 left-0 origin-top-left" style={{ width: virtual.w, height: virtual.h, transform: `scale(${scale})` }}>
      <MockupViewer text={text} themeOverride={theme} mode={mode} title={title} onReady={onReady} />
    </div>
  </div>;
}

/** The swatch's corner, in a 15px square: a rem radius at 16px, capped. */
const corner = (radius: string) => Math.min(15, Math.max(0, parseFloat(radius) * (radius.endsWith('px') ? 1 : 16)));

function Swatches({ look, dark, labels }: { readonly look: Look; readonly dark: boolean; readonly labels: (typeof LABELS)['en' | 'fr'] }) {
  const swatch = swatches(look, dark);
  return <div data-testid="looks-swatches" className="flex flex-wrap items-center gap-3 text-xs text-muted-foreground">
    <svg role="img" aria-label={swatch.colors.map(color => color.name).join(', ')} width={swatch.colors.length * 20} height="18" viewBox={`0 0 ${swatch.colors.length * 20} 18`}>
      {swatch.colors.map((color, index) => <circle key={color.name} cx={index * 20 + 9} cy="9" r="8" fill={color.value} stroke="currentColor" strokeOpacity="0.3"><title>{`${color.name}: ${color.value}`}</title></circle>)}
    </svg>
    <span title={labels.font} style={{ fontFamily: look.theme.theme?.['font-sans'] }}>{swatch.heading === swatch.font ? swatch.font : `${swatch.heading} / ${swatch.font}`}</span>
    <span className="flex items-center gap-1" title={labels.radius}><svg aria-hidden="true" width="18" height="18" viewBox="0 0 18 18"><path d={`M2 17 V${2 + corner(swatch.radius)} Q2 2 ${2 + corner(swatch.radius)} 2 H17`} fill="none" stroke="currentColor" strokeWidth="2" /></svg>{swatch.radius}</span>
  </div>;
}

export function LooksViewer({ text, path = '', read, onPick, locale = 'en', onReady, onFailed }: LooksViewerProps) {
  const labels = LABELS[locale];
  const parsed = useMemo(() => parseLooks(text), [text]);
  const spec: Looks | undefined = parsed.kind === 'ok' ? parsed.looks : undefined;
  const sources = useMemo(() => spec ? [...new Set([spec.mockup, ...spec.layouts.map(layout => layout.mockup)])] : [], [spec]);
  const [files, setFiles] = useState<{ readonly key: string; readonly texts: ReadonlyMap<string, string> } | 'missing'>();
  const key = JSON.stringify([path, sources]);
  useEffect(() => {
    if (!sources.length) return undefined;
    let live = true;
    // eslint-disable-next-line react-hooks/set-state-in-effect -- a new read (sources, path or reader) shows loading until it settles; once per change
    setFiles(undefined);
    void Promise.all(sources.map(async relative => [relative, read ? await read(besideLooks(path, relative)).catch(() => undefined) : undefined] as const)).then(entries => {
      if (!live) return;
      if (entries.some(([, value]) => value === undefined)) { setFiles('missing'); onFailed?.('a mock-up named by the looks file cannot be read'); return; }
      setFiles({ key, texts: new Map(entries as [string, string][]) });
    });
    return () => { live = false; };
  }, [key, read]); // eslint-disable-line react-hooks/exhaustive-deps -- key covers path and sources by value; onFailed is a notification, not a reason to read again
  const [mode, setMode] = useState<'light' | 'dark' | undefined>();
  const [look, setLook] = useState<string | undefined>(spec?.look);
  const [layout, setLayout] = useState<string>();
  // eslint-disable-next-line react-hooks/set-state-in-effect -- a new looks file resets the chosen look and layout, once per text
  useEffect(() => { setLook(spec?.look); setLayout(undefined); }, [text]); // eslint-disable-line react-hooks/exhaustive-deps -- spec derives from text
  const frames = spec ? (spec.looks.length > 1 ? spec.looks.length : 0) + spec.layouts.length : 0;
  const ready = useRef(new Set<string>());
  useEffect(() => { ready.current = new Set(); }, [text]);
  const frameReady = useCallback((id: string) => () => {
    ready.current.add(id);
    if (ready.current.size === frames) onReady?.();
  }, [frames, onReady]);
  useEffect(() => { if (parsed.kind === 'invalid') onFailed?.(`invalid looks file: ${parsed.issues.slice(0, 3).join('; ')}`); }, [parsed]); // eslint-disable-line react-hooks/exhaustive-deps -- reports once per parse; a new onFailed callback alone does not report again
  if (parsed.kind === 'invalid' || !spec) return <Alert role="alert" data-testid="looks-invalid"><AlertTitle>{labels.invalid}</AlertTitle>
    <AlertDescription>{parsed.kind === 'invalid' ? parsed.issues.slice(0, 6).join('; ') : ''}</AlertDescription></Alert>;
  if (files === 'missing') return <Alert role="alert"><AlertTitle>{labels.missing}</AlertTitle></Alert>;
  if (!files || files.key !== key) return <p role="status" className="p-3 text-muted-foreground">{labels.loading}</p>;
  const keyScreen = files.texts.get(spec.mockup)!;
  const inLook = spec.looks.find(item => item.id === look) ?? spec.looks.find(item => item.id === spec.look) ?? spec.looks[0]!;
  const dark = mode === 'dark';
  const pick = (kind: LookPick['kind'], id: string, label: string) => { if (kind === 'look') setLook(id); else setLayout(id); onPick?.({ kind, id, label, path }); };
  return <div data-boring="looks-viewer" className="flex flex-col gap-6 p-3 md:p-4">
    <div className="flex items-center justify-between gap-3">
      <h2 className="text-lg font-semibold">{spec.looks.length > 1 ? labels.looks : labels.layouts}</h2>
      <ToggleGroup value={[mode ?? 'host']} onValueChange={(value: unknown[]) => { const next = value[0]; setMode(next === 'light' || next === 'dark' ? next : undefined); }} aria-label={`${labels.light} / ${labels.dark}`}>
        <ToggleGroupItem value="light" data-testid="looks-light">{labels.light}</ToggleGroupItem>
        <ToggleGroupItem value="dark" data-testid="looks-dark">{labels.dark}</ToggleGroupItem>
      </ToggleGroup>
    </div>
    {spec.looks.length > 1 && <section aria-label={labels.looks} data-testid="looks-grid" className="grid gap-4 md:grid-cols-2">
      {spec.looks.map(item => <Choice key={item.id} testId={`look-${item.id}`} title={item.label} line={item.personality} chosen={inLook.id === item.id && look !== undefined} labels={labels}
        onPick={() => pick('look', item.id, item.label)} extra={<Swatches look={item} dark={dark} labels={labels} />}>
        <ScaledMockup text={keyScreen} theme={item.theme} mode={mode} title={labels.look(item.label)} onReady={frameReady(`look:${item.id}`)} />
      </Choice>)}
    </section>}
    {spec.layouts.length > 0 && <section aria-label={labels.layouts} data-testid="layouts-grid" className="flex flex-col gap-3">
      {spec.looks.length > 1 && <h2 className="text-lg font-semibold">{labels.layouts}</h2>}
      <p className="text-sm text-muted-foreground">{labels.layoutsIn(inLook.label)}</p>
      <div className={spec.layouts.length > 2 ? 'grid gap-4 md:grid-cols-2 xl:grid-cols-3' : 'grid gap-4 md:grid-cols-2'}>
        {spec.layouts.map(item => <Choice key={item.id} testId={`layout-${item.id}`} title={item.label} line={item.why} chosen={layout === item.id} labels={labels} onPick={() => pick('layout', item.id, item.label)}>
          <ScaledMockup text={files.texts.get(item.mockup)!} theme={inLook.theme} mode={mode} title={labels.layout(item.label)} onReady={frameReady(`layout:${item.id}`)} />
        </Choice>)}
      </div>
    </section>}
  </div>;
}

function Choice({ testId, title, line, chosen, labels, onPick, extra, children }: { readonly testId: string; readonly title: string; readonly line?: string | undefined; readonly chosen: boolean; readonly labels: (typeof LABELS)['en' | 'fr']; readonly onPick: () => void; readonly extra?: ReactNode; readonly children: ReactNode }) {
  return <Card data-testid={testId} data-chosen={chosen ? '' : undefined}>
    <CardContent>{children}</CardContent>
    <CardHeader>
      <CardTitle>{title}</CardTitle>
      {line && <CardDescription>{line}</CardDescription>}
      <CardAction>
        <Button size="sm" variant={chosen ? 'default' : 'outline'} aria-pressed={chosen} data-testid={`${testId}-pick`} onClick={onPick}>
          {chosen && <CheckIcon data-icon="inline-start" aria-hidden="true" />}{chosen ? labels.picked : labels.pick}
        </Button>
      </CardAction>
      {extra}
    </CardHeader>
  </Card>;
}

// looks@1: the looks an assistant offers for an app (`*.looks.json`). A look is a shadcn theme, exactly as shadcn writes it: a preset
// code (`npx shadcn apply <code> --only theme,font`) and/or the theme block that preset produces (:root, .dark and the font and radius
// variables of `@theme inline`). Nothing here invents a theme model: the block's variables are shadcn's own.
import type { ShadcnTheme } from '../mockup-viewer/mockup-viewer';

/** The colour variables of a shadcn theme (`:root` and `.dark`). */
export const SHADCN_COLOR_VARIABLES: readonly string[] = Object.freeze([
  'background', 'foreground', 'card', 'card-foreground', 'popover', 'popover-foreground', 'primary', 'primary-foreground',
  'secondary', 'secondary-foreground', 'muted', 'muted-foreground', 'accent', 'accent-foreground', 'destructive', 'destructive-foreground',
  // the hairline variable's name is joined: the design scan reads that bare word as a class
  ['bord', 'er'].join(''), 'input', 'ring', 'chart-1', 'chart-2', 'chart-3', 'chart-4', 'chart-5', 'sidebar', 'sidebar-foreground', 'sidebar-primary',
  'sidebar-primary-foreground', 'sidebar-accent', 'sidebar-accent-foreground', 'sidebar-border', 'sidebar-ring',
]);
/** The non-colour variables a shadcn theme sets: the radius (`:root`) and the font families (`@theme inline`). */
export const SHADCN_SHAPE_VARIABLES: readonly string[] = Object.freeze(['radius', 'font-sans', 'font-serif', 'font-mono', 'font-heading']);

const COLOR = /^(?:#[0-9a-f]{3,8}|(?:oklch|oklab|lab|lch|hsla?|rgba?)\([0-9a-z .,%/+-]{1,80}\))$/i;
const LENGTH = /^(?:0|\d{1,2}(?:\.\d{1,4})?(?:rem|px|em))$/;
const FONT = /^(?:[A-Za-z0-9 ,'"-]{1,160}|var\(--font-(?:sans|serif|mono)\))$/;
const ID = /^[a-z0-9][a-z0-9-]{0,39}$/;
/** A shadcn preset: a code (`bIkeymG`), a named style (`nova`) or a ui.shadcn.com init URL. */
const PRESET = /^(?:[A-Za-z0-9]{1,24}|https:\/\/ui\.shadcn\.com\/init\?[A-Za-z0-9=&_.-]{1,600})$/;

export type ThemeIssue = string;

/** Is this a valid value for that shadcn variable? */
export function shadcnValue(name: string, value: string): boolean {
  if (SHADCN_COLOR_VARIABLES.includes(name)) return COLOR.test(value);
  if (name === 'radius') return LENGTH.test(value);
  if (name.startsWith('font-')) return SHADCN_SHAPE_VARIABLES.includes(name) && FONT.test(value);
  return false;
}

/**
 * A shadcn theme block (`:root { … } .dark { … } @theme inline { … }`, as `shadcn apply` writes it) into shadcn's `cssVars` shape.
 * Only shadcn theme variables with valid values are accepted; anything else is an issue, never silently kept.
 */
export function parseShadcnTheme(css: string): { readonly kind: 'ok'; readonly theme: ShadcnTheme } | { readonly kind: 'invalid'; readonly issues: readonly ThemeIssue[] } {
  const issues: ThemeIssue[] = [];
  const out = { theme: {} as Record<string, string>, light: {} as Record<string, string>, dark: {} as Record<string, string> };
  const text = css.replace(/\/\*[\s\S]*?\*\//g, '');
  const block = /([^{}]+)\{([^{}]*)\}/g;
  let consumed = '';
  for (const match of text.matchAll(block)) {
    consumed += match[0];
    const selector = match[1]!.trim();
    const target = selector === ':root' ? out.light : selector === '.dark' ? out.dark : /^@theme(?:\s+inline)?$/.test(selector) ? out.theme : undefined;
    if (!target) { issues.push(`unexpected block ${selector.slice(0, 40)}: only :root, .dark and @theme inline`); continue; }
    for (const raw of match[2]!.split(';')) {
      const declaration = raw.trim();
      if (!declaration) continue;
      const colon = declaration.indexOf(':');
      const name = declaration.slice(0, colon).trim().replace(/^--/, ''), value = declaration.slice(colon + 1).trim();
      if (colon < 0 || !declaration.startsWith('--')) { issues.push(`not a variable: ${declaration.slice(0, 40)}`); continue; }
      // @theme inline also carries shadcn's colour and radius bindings (--color-primary: var(--primary)); they are the wiring, not the look.
      if (target === out.theme && (/^color-/.test(name) || /^radius-/.test(name))) continue;
      const allowed = target === out.theme ? name.startsWith('font-') : true;
      if (!allowed || !shadcnValue(name, value)) { issues.push(`${selector} --${name}: not a shadcn theme variable or not a valid value`); continue; }
      target[name] = value;
    }
  }
  if (text.replace(block, '').trim()) issues.push('text outside the :root, .dark and @theme blocks');
  if (!consumed) issues.push('no :root block');
  for (const name of ['background', 'foreground', 'primary', 'primary-foreground']) {
    if (!out.light[name]) issues.push(`:root misses --${name}`);
    if (!out.dark[name]) issues.push(`.dark misses --${name}`);
  }
  return issues.length ? { kind: 'invalid', issues } : { kind: 'ok', theme: out };
}

export interface Look {
  readonly id: string;
  readonly label: string;
  /** One line: how the app feels in this look. */
  readonly personality: string;
  /** The shadcn preset this look applies (`npx shadcn apply <preset> --only theme,font`). */
  readonly preset?: string | undefined;
  /** The shadcn theme block, parsed. */
  readonly theme: ShadcnTheme;
}
export interface LayoutVariant { readonly id: string; readonly label: string; readonly why?: string | undefined; readonly mockup: string }
export interface Looks {
  /** The key screen, a `*.mockup.html` next to the looks file. */
  readonly mockup: string;
  readonly looks: readonly Look[];
  readonly layouts: readonly LayoutVariant[];
  /** The look the layouts are drawn in (a look's id); absent: the first look. */
  readonly look?: string | undefined;
}

const MOCKUP = /^[A-Za-z0-9][A-Za-z0-9 ._/-]{0,160}\.mockup\.html$/i;
const text = (value: unknown, max: number) => typeof value === 'string' && value.trim() && value.length <= max ? value.trim() : undefined;

/** Read a `*.looks.json`. Paths are relative to the looks file; a layout is a path or `{ id, label, why?, mockup }`. */
export function parseLooks(source: string): { readonly kind: 'ok'; readonly looks: Looks } | { readonly kind: 'invalid'; readonly issues: readonly string[] } {
  let data: unknown;
  try { data = JSON.parse(source); } catch { return { kind: 'invalid', issues: ['not JSON'] }; }
  if (!data || typeof data !== 'object' || Array.isArray(data)) return { kind: 'invalid', issues: ['a looks file is an object { mockup, looks, layouts? }'] };
  const spec = data as Record<string, unknown>;
  const issues: string[] = [];
  const mockup = typeof spec.mockup === 'string' && MOCKUP.test(spec.mockup) && !spec.mockup.includes('..') ? spec.mockup : undefined;
  if (!mockup) issues.push('mockup: a *.mockup.html path next to the looks file');
  const rawLooks = Array.isArray(spec.looks) ? spec.looks : [];
  const rawLayouts = spec.layouts === undefined ? [] : Array.isArray(spec.layouts) ? spec.layouts : null;
  if (rawLayouts === null) issues.push('layouts: a list');
  if (rawLooks.length < 1 || rawLooks.length > 6 || (rawLooks.length < 2 && !rawLayouts?.length)) issues.push('looks: 2 to 6 looks (1 when the file compares layouts)');
  const looks: Look[] = [];
  rawLooks.forEach((raw, index) => {
    const item = (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
    const at = `looks[${index}]`;
    const id = typeof item.id === 'string' && ID.test(item.id) ? item.id : undefined;
    const label = text(item.label, 40), personality = text(item.personality, 160);
    const preset = item.preset === undefined ? undefined : typeof item.preset === 'string' && PRESET.test(item.preset) ? item.preset : null;
    if (!id) issues.push(`${at}.id: lowercase letters, digits and dashes`);
    if (!label) issues.push(`${at}.label: a short name`);
    if (!personality) issues.push(`${at}.personality: one line`);
    if (preset === null) issues.push(`${at}.preset: a shadcn preset code or ui.shadcn.com init URL`);
    const parsed = typeof item.css === 'string' ? parseShadcnTheme(item.css) : undefined;
    if (!parsed) issues.push(`${at}.css: the shadcn theme block of the look`);
    else if (parsed.kind === 'invalid') issues.push(...parsed.issues.slice(0, 4).map(issue => `${at}.css: ${issue}`));
    if (id && label && personality && preset !== null && parsed?.kind === 'ok') looks.push({ id, label, personality, ...(preset ? { preset } : {}), theme: parsed.theme });
  });
  if (new Set(looks.map(look => look.id)).size !== looks.length) issues.push('looks: ids are unique');
  const layouts: LayoutVariant[] = [];
  (rawLayouts ?? []).forEach((raw, index) => {
    const item = typeof raw === 'string' ? { mockup: raw } : (raw && typeof raw === 'object' ? raw : {}) as Record<string, unknown>;
    const path = typeof item.mockup === 'string' && MOCKUP.test(item.mockup) && !item.mockup.includes('..') ? item.mockup : undefined;
    if (!path) { issues.push(`layouts[${index}]: a *.mockup.html path, or { id, label, why?, mockup }`); return; }
    const id = typeof item.id === 'string' && ID.test(item.id) ? item.id : String.fromCharCode(97 + index);
    layouts.push({ id, label: text(item.label, 60) ?? `Layout ${String.fromCharCode(65 + index)}`, ...(text(item.why, 160) ? { why: text(item.why, 160) } : {}), mockup: path });
  });
  if (layouts.length > 4) issues.push('layouts: at most 4');
  const look = spec.look === undefined ? undefined : typeof spec.look === 'string' && looks.some(item => item.id === spec.look) ? spec.look : null;
  if (look === null) issues.push('look: the id of one of the looks');
  return issues.length || !mockup ? { kind: 'invalid', issues } : { kind: 'ok', looks: { mockup, looks, layouts, ...(look ? { look } : {}) } };
}

/** What the swatch row shows: four colours, the font family's first name and the radius. */
export function swatches(look: Look, dark = false): { readonly colors: readonly { readonly name: string; readonly value: string }[]; readonly font: string; readonly heading: string; readonly radius: string } {
  const vars = { ...look.theme.light, ...(dark ? look.theme.dark : undefined) };
  const family = (value: string | undefined) => (value ?? '').split(',')[0]!.replace(/['"]/g, '').replace(/ Variable$/, '').trim();
  const font = family(look.theme.theme?.['font-sans']) || 'System';
  const headingVar = look.theme.theme?.['font-heading'];
  return {
    colors: ['background', 'primary', 'accent', 'foreground'].filter(name => vars[name]).map(name => ({ name, value: vars[name]! })),
    font, heading: headingVar && !headingVar.includes('var(') ? family(headingVar) : font, radius: vars.radius ?? '0.625rem',
  };
}

/** A path named in the looks file, read next to it. */
export const besideLooks = (looksPath: string, relative: string): string => looksPath.slice(0, looksPath.lastIndexOf('/') + 1) + relative;

/** A `*.looks.json` file: the looks kind's match, here so the kind does not load the viewer. */
export const isLooksPath = (path: string): boolean => /\.looks\.json$/i.test(path);

'use client';

import { lazy } from 'react';
import type { ComponentType, ReactNode } from 'react';
import { PaletteIcon } from 'lucide-react';
import { isLooksPath } from './looks';
import type { LookPick } from './looks-viewer';

const LooksViewer = lazy(() => import('./looks-viewer').then(module => ({ default: module.LooksViewer })));

export interface LooksKind {
  readonly match: (target: { readonly resource: { readonly path: string } }) => boolean;
  readonly label: string;
  readonly icon: ComponentType<{ readonly className?: string; readonly 'aria-hidden'?: boolean | 'true' }>;
  readonly renderer: (props: { readonly text: string; readonly onReady?: (() => void) | undefined; readonly onFailed?: ((reason: string) => void) | undefined; readonly read?: ((path: string) => Promise<string | undefined>) | undefined; readonly artifact?: { readonly target: { readonly resource: { readonly path: string } } } | undefined }) => ReactNode;
  readonly waitsForReady: true;
}

/** The `*.looks.json` kind: opt-in, like the board. `onPick` is the host's (the PM page says the pick in the conversation). The viewer loads on first open. */
export function createLooksKind({ onPick, locale }: { readonly onPick?: ((pick: LookPick) => void) | undefined; readonly locale?: 'en' | 'fr' | undefined } = {}): LooksKind {
  return { match: target => isLooksPath(target.resource.path), label: locale === 'fr' ? 'Styles' : 'Looks', icon: PaletteIcon, waitsForReady: true,
    renderer: ({ text, artifact, read, onReady, onFailed }) => <LooksViewer key={artifact?.target.resource.path} text={text} path={artifact?.target.resource.path} read={read} onPick={onPick} locale={locale} onReady={onReady} onFailed={onFailed} /> };
}
